import{_ as t,o as a,c as i,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"毛泽东思想与方法论索引","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/mao-zedong/index.md","filePath":"topics/mao-zedong/index.md"}'),n={name:"topics/mao-zedong/index.md"};function r(s,o,l,d,c,h){return a(),i("div",null,[...o[0]||(o[0]=[e('<h1 id="毛泽东思想与方法论索引" tabindex="-1">毛泽东思想与方法论索引 <a class="header-anchor" href="#毛泽东思想与方法论索引" aria-label="Permalink to &quot;毛泽东思想与方法论索引&quot;">​</a></h1><blockquote><p>主题：毛泽东哲学、著作拆解、革命方法论迁移到工程/职场/团队</p></blockquote><hr><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><ol><li><p><a href="/zhishiku-reading/topics/mao-zedong/class-analysis-friend-enemy.html"><strong>《中国社会各阶级的分析》：辨明敌友的科学方法</strong></a> — 调研利益结构 → 划分敌友立场 → 定&quot;依靠/联合/提防/反对&quot;策略。核心命题&quot;谁是敌人谁是朋友&quot;+ 各阶层决策表 + 当代职场/团队迁移。</p><ul><li>关联：实践论矛盾论、游泳&quot;沉腿=表面归因&quot;、天轴困局、创业定位</li></ul></li><li><p><a href="/zhishiku-reading/topics/mao-zedong/mao-philosophy-practice-contradiction.html"><strong>毛泽东哲学：实践论 + 矛盾论</strong></a> — 认识论的螺旋（实践→认识→再实践）、矛盾的普遍性/特殊性、主次矛盾。方法论母版。</p></li><li><p><a href="/zhishiku-reading/topics/mao-zedong/mao-collected-works.html"><strong>《毛泽东文集》八卷要点</strong></a> — 八卷著作的要点摘编，绝境生存方法论集。</p></li><li><p><a href="/zhishiku-reading/topics/mao-zedong/winning-feel-class-habitus.html"><strong>《&quot;赢的手感&quot;：被制度识别的阶级惯习》（布迪厄）</strong></a> — 惯习/文化资本/阶级再生产；与毛选阶级分析中西对照——布迪厄讲&quot;阶级如何无声再生产&quot;，毛选讲&quot;辨敌友该站哪边&quot;，互补。</p></li><li><p><a href="/zhishiku-reading/topics/mao-zedong/tianya-maoism-mapping.html"><strong>天涯神贴 ↔ 毛泽东思想：逐条对照与核实</strong></a> ⭐ — 用户长文命题（&quot;那批天涯幸存者，在不知道毛泽东的情况下，用真金白银重新发明了一半毛泽东思想&quot;）的<strong>逐条核验版</strong>：毛著侧用 marxists.org 原文逐字对，天涯侧锚回 <code>tianya/handbook/</code> 帖号，六类失真框架列勘误表。<strong>结论：6 条主干对照全部成立，但 4 处引用需修正</strong>（如「战略上藐视敌人，战术上重视敌人」实出 1957《一切反动派都是纸老虎》而非《论持久战》；「存人失地」在所核毛著中未见）。附带一条增量洞察：<strong>从约束推出的只能是结构，不会是时点</strong> —— 这才是「结构层准、点位层不准」的机制解释。</p><ul><li>关联：<code>topics/tianya/</code>（全部手册）、class-analysis-friend-enemy、mao-philosophy-practice-contradiction、tianya/prediction-ledger</li></ul></li></ol><hr><h2 id="母题钩子" tabindex="-1">母题钩子 <a class="header-anchor" href="#母题钩子" aria-label="Permalink to &quot;母题钩子&quot;">​</a></h2><ul><li><strong>没有调查没有发言权</strong> → 决策前必先摸清客观情况/利益结构</li><li><strong>把朋友搞得多多的，把敌人搞得少少的</strong> → 结构性取舍，集中力量结盟关键支点</li><li><strong>分清敌友/主次矛盾</strong> → 不凭感觉，靠实地调研 + 利益分析</li></ul>',8)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
